<script setup>
import {computed,defineAsyncComponent,onMounted,onUnmounted,reactive,ref,shallowRef,toRaw} from 'vue';
import {STRATEGIES,COMBINABLE,GRADES,choose} from '../engine.mjs';
import {backtestOptions} from '../echarts-options.mjs';
import {fmt,money,pad,freshSeed,downloadCsv} from '../utils.js';
import Balls from './Balls.vue';
import MultiSpreadControls from './MultiSpreadControls.vue';
import MultiStability from './MultiStability.vue';
const EChart=defineAsyncComponent(()=>import('./EChart.vue'));
const props=defineProps({draws:Array});
const emit=defineEmits(['error']);
const config=reactive({strategy:'hot100',methods:['hot100','cold100','zones'],redPool:12,bluePool:4,tickets:5,maxOverlap:5,blueMode:'random',seed:20261001,periods:1000,end:props.draws.length});
const result=shallowRef(null),running=ref(false),stage=ref(''),progress=ref(0),expanded=ref(null),page=ref(0),winsOnly=ref(false);
let worker;
const strategies=Object.entries(STRATEGIES).filter(([key])=>key!=='manual');
const percent=n=>(n*100).toFixed(1)+'%';
const filtered=computed(()=>result.value?[...result.value.records].reverse().filter(row=>!winsOnly.value||row.tickets.some(ticket=>ticket.counts.slice(1).some(Boolean))):[]);
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10)));
const shown=computed(()=>filtered.value.slice(page.value*10,page.value*10+10));
const chart=computed(()=>result.value?backtestOptions(result.value.records,'cumulative',false):{});
function run(newSeed=false){
 if(running.value)return;if(newSeed)config.seed=freshSeed();running.value=true;progress.value=0;stage.value='准备生成每期号码';emit('error','');
 worker=new Worker(new URL('../multibet-worker.mjs',import.meta.url),{type:'module'});
 const stop=()=>{worker?.terminate();worker=null;running.value=false;};
 worker.onmessage=({data})=>{if(data.progress!==undefined){stage.value=data.stage;progress.value=data.progress;return;}stop();if(data.error)emit('error',data.error);else{result.value=data.result;page.value=0;expanded.value=null;}};
 worker.onerror=()=>{stop();emit('error','多注实验运行失败，请重试。');};
 worker.postMessage({draws:toRaw(props.draws),config:structuredClone(toRaw(config))});
}
function cancel(){worker?.terminate();worker=null;running.value=false;}
function exportResult(){
 const r=result.value;if(!r)return;
 const rows=r.records.flatMap(row=>row.tickets.map((ticket,i)=>[row.issue,row.date,i+1,ticket.pick.red.map(pad).join(' '),ticket.pick.blue.map(pad).join(' '),ticket.redHits,ticket.blueHit,GRADES[ticket.counts.slice(1).findIndex(Boolean)+1]||'未中奖',ticket.payout,2,ticket.unknown]));
 downloadCsv(`多注实验_${r.startIssue}-${r.endIssue}_${r.config.seed}.csv`,[['规则',STRATEGIES[r.config.strategy],'每期注数',r.config.tickets,'候选红球',r.config.redPool,'候选蓝球',r.config.bluePool,'随机编号',r.config.seed,'红球重复上限',r.config.maxOverlap,'蓝球模式',r.config.blueMode],['期号','日期','注号','红球','蓝球','命中红球','命中蓝球','最高奖级','奖金','投入','未知奖金注数'],...rows]);
}
onMounted(async()=>{try{const response=await fetch(`${import.meta.env.BASE_URL}multibet.json`);if(response.ok){const data=await response.json();if(data.version===2&&data.endIssue===props.draws.at(-1).issue)result.value=data;}}catch{}});
onUnmounted(cancel);
</script>
<template>
 <main id="multibet" class="tab-panel"><div class="multi-heading"><p class="eyebrow">MULTI TICKET / RANDOM COMBINATIONS</p><h2>一套规则，每期打不同的多注号码</h2><p>从规则选出的候选池里随机取6红＋1蓝，每注的红球组合不同；各注允许共享部分红球，蓝球可以重复。</p></div><div class="experiment-layout"><aside class="card config"><h3>多注实验设置</h3><form @submit.prevent="run()"><fieldset :disabled="running"><label for="multi-strategy">候选号码规则</label><select id="multi-strategy" v-model="config.strategy"><option v-for="[key,label] in strategies" :key="key" :value="key">{{ label }}</option></select><fieldset v-if="config.strategy==='combined'" class="multi-methods"><legend>组合规则（至少两种）</legend><label v-for="[key,label] in COMBINABLE" :key="key" class="check-row"><input v-model="config.methods" type="checkbox" :value="key" /><span>{{ label }}</span></label></fieldset><label for="multi-red">红球候选池大小</label><input id="multi-red" v-model.number="config.redPool" type="number" min="6" max="33" required /><label for="multi-blue">蓝球候选池大小</label><input id="multi-blue" v-model.number="config.bluePool" type="number" min="1" max="16" required /><label for="multi-tickets">每期生成几注</label><input id="multi-tickets" v-model.number="config.tickets" type="number" min="1" :max="Math.min(100,choose(config.redPool,6))" required /><p class="field-help">每注从红球池等概率抽6个、蓝球池抽1个；重复红球组合会重抽。{{ config.redPool }}个候选红球最多能组成{{ fmt(choose(config.redPool,6)) }}组不同红球。只购买生成的{{ config.tickets }}注，不展开整个候选池。</p><MultiSpreadControls v-model:max-overlap="config.maxOverlap" v-model:blue-mode="config.blueMode" /><label for="multi-periods">回测期数</label><input id="multi-periods" v-model.number="config.periods" type="number" min="1" :max="config.end-500" required /><label for="multi-end">截止开奖期</label><select id="multi-end" v-model.number="config.end"><option v-for="(row,index) in draws.slice(500).reverse()" :key="row.issue" :value="draws.length-index">{{ row.issue }} · {{ row.date }}</option></select><label for="multi-seed">固定随机编号</label><input id="multi-seed" v-model.number="config.seed" type="number" min="1" max="4294967295" required /><p class="field-help">相同数据、配置和编号可复现结果。换编号只换候选池内的随机组号。</p><div class="stake-box"><div><span>每期投入</span><strong>{{ money(config.tickets*2) }}</strong></div><p>{{ config.tickets }}注 × ¥2 · 全程 {{ money(config.tickets*2*config.periods) }}</p></div><button class="primary" type="submit">运行多注回测</button><button class="secondary" type="button" style="margin-top:12px;width:100%" @click="run(true)">换随机编号再跑一次</button></fieldset></form><div v-if="running" class="multi-progress" role="status">{{ stage }} · {{ Math.round(progress*100) }}%<button class="tiny-button" @click="cancel">停止</button></div></aside>
 <section class="results"><template v-if="result"><div class="result-heading"><div><h2>{{ STRATEGIES[result.config.strategy] }} · 每期{{ result.config.tickets }}注</h2><p>{{ result.startIssue }}—{{ result.endIssue }} · {{ result.periods }}期 · {{ result.config.redPool }}红 / {{ result.config.bluePool }}蓝候选池 · 编号 {{ result.config.seed }}</p></div><button class="secondary" @click="exportResult">导出每注明细</button></div><div class="metrics"><article class="metric"><span>模拟总投入</span><strong>{{ money(result.cost) }}</strong><small>每期 {{ money(result.costPerPeriod) }}</small></article><article class="metric"><span>{{ result.unknown?'已知奖金下限':'奖金合计' }}</span><strong>{{ result.unknown?'≥':'' }}{{ money(result.prize) }}</strong><small>按每注分别计奖 · 税前</small></article><article class="metric" :class="result.net<0?'loss':'profit'"><span>模拟净额</span><strong>{{ result.unknown?'≥':'' }}{{ money(result.net) }}</strong><small>奖金 / 投入 {{ percent(result.returnRate) }}</small></article><article class="metric"><span>中奖期比例</span><strong>{{ percent(result.winRate) }}</strong><small>{{ result.winningPeriods }}期至少一注中奖</small></article></div><div class="card padded multi-comparison"><h3>与同成本随机打{{ result.config.tickets }}注比较</h3><p>本方案回报率 <b>{{ result.unknown?'≥':'' }}{{ percent(result.returnRate) }}</b> · {{ result.random.samples }}组随机策略平均 <b>{{ percent(result.random.meanReturn) }}</b>，中位数 <b>{{ percent(result.random.medianReturn) }}</b>。</p><p>本方案中奖期比例 {{ percent(result.winRate) }} · 随机平均 {{ percent(result.random.meanWin) }} · 回报率超过 {{ percent(result.random.percentile) }} 的随机样本。</p><p class="field-help">对照组从全部33红、16蓝随机组号，每期同样生成不同红球的{{ result.config.tickets }}注。随机回报率经验95%范围：{{ percent(result.random.low) }}—{{ percent(result.random.high) }}。少量大额奖会显著拉高平均值，中位数表示中间水平。这是固定编号的一次历史实验，不能只挑表现最好的随机编号推断未来优势。</p></div><MultiStability :result="result" /><div class="card chart-card"><h3>累计投入与奖金</h3><EChart :option="chart" label="多注实验累计投入与奖金" /></div><section class="card padded multi-next"><h3>{{ result.endIssue===draws.at(-1).issue?'下一期':'截止所选期之后一期' }}按同规则生成的{{ result.config.tickets }}注参考</h3><p class="field-help">候选池仅使用截止{{ result.endIssue }}期之前及该期的已开奖数据。</p><p>红球候选池</p><Balls :red="result.next.redPool" /><p>蓝球候选池</p><Balls :blue="result.next.bluePool" /><div v-for="(ticket,index) in result.next.tickets" :key="index" class="multi-ticket"><span>第{{ index+1 }}注</span><Balls :red="ticket.red" :blue="ticket.blue" /></div></section><section class="card table-card"><div class="card-heading"><div><h3>逐期与每注明细</h3><p>展开可查看每注所选号码、命中数和奖金。</p></div><label class="check-row"><input v-model="winsOnly" type="checkbox" @change="page=0" /><span>只看中奖期</span></label></div><div class="table-wrap"><table><thead><tr><th>期号 / 日期</th><th>中奖注数</th><th>当期投入</th><th>奖金</th><th>净额</th><th></th></tr></thead><tbody><template v-for="row in shown" :key="row.issue"><tr><td>{{ row.issue }}<br /><small>{{ row.date }}</small></td><td>{{ row.tickets.filter(ticket=>ticket.counts.slice(1).some(Boolean)).length }}</td><td>{{ money(row.cost) }}</td><td>{{ row.unknown?'≥':'' }}{{ money(row.payout) }}</td><td>{{ row.unknown?'≥':'' }}{{ money(row.net) }}</td><td><button class="tiny-button" :aria-expanded="expanded===row.issue" @click="expanded=expanded===row.issue?null:row.issue">{{ expanded===row.issue?'收起':'展开' }}</button></td></tr><tr v-if="expanded===row.issue" class="detail-expansion"><td colspan="6"><p>实际开奖</p><Balls :red="row.actualRed" :blue="[row.actualBlue]" /><div v-for="(ticket,index) in row.tickets" :key="index" class="multi-ticket"><span>第{{ index+1 }}注</span><Balls :red="ticket.pick.red" :blue="ticket.pick.blue" :actual="{red:row.actualRed,blue:row.actualBlue}" /><span>{{ ticket.redHits }}红＋{{ ticket.blueHit }}蓝 · {{ ticket.unknown?'≥':'' }}{{ money(ticket.payout) }}</span></div></td></tr></template><tr v-if="!shown.length"><td colspan="6">没有符合条件的开奖期。</td></tr></tbody></table></div><div class="pager"><span>{{ page+1 }} / {{ pages }}页</span><div class="pager-buttons"><button class="secondary" :disabled="page===0" @click="page--;expanded=null">上一页</button><button class="secondary" :disabled="page>=pages-1" @click="page++;expanded=null">下一页</button></div></div></section><p class="field-help">每期取号只读取此前开奖。各注独立计奖，投入按实际生成注数计算；热门候选池与随机组号的历史表现不代表下一期更高中奖概率。</p></template><div v-else class="card padded"><h3>配置候选池和每期注数，再运行实验</h3><p>例如：近100期热号前12个红球、前4个蓝球，每期随机组5注，每期¥10。</p></div></section></div></main>
</template>
<style scoped>
.multi-heading{margin-bottom:24px}.multi-heading h2{font-size:25px}.multi-heading>p:last-child{color:#66818f;line-height:1.8;font-size:14px}.config fieldset{padding:0;border:0;margin:0}.multi-methods legend{margin-top:14px;font-size:13px}.multi-progress{font-size:12px;line-height:1.8;margin-top:15px}.multi-progress button{margin-left:12px}.multi-comparison,.multi-next{margin-bottom:24px}.multi-comparison>p,.multi-next>p{font-size:13px;line-height:1.8}.multi-ticket{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:14px 0}.multi-ticket>span{font-size:12px;color:#607b88}.multi-next .multi-ticket{padding-top:12px;border-top:1px solid #e2eaee}.multi-next .balls{flex-wrap:wrap}.detail-expansion .multi-ticket{margin:14px 0}.detail-expansion p{font-size:12px;color:#68838f}@media(max-width:760px){.multi-heading h2{font-size:22px}}
</style>
